@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#17231c;--muted:#758078;--line:#e4e9e3;--green:#246849;--bright:#c1ef62;--paper:#f7f8f5;--white:#fff;--red:#cb6258;--gold:#a97932;font-family:'DM Sans',system-ui,sans-serif;color:var(--ink);background:#f2f4f0;font-synthesis:none}
*{box-sizing:border-box}
body{margin:0;min-width:320px;min-height:100vh;background:#f2f4f0}
button,input{font:inherit}
button{cursor:pointer}
button:focus-visible,input:focus-visible{outline:3px solid #9ed35c;outline-offset:2px}
.app-shell{max-width:1600px;margin:0 auto;padding:0 36px 22px}
.topbar{height:68px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #dfe4dd}
.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink);font-weight:800;font-size:15px;letter-spacing:.11em}
.brand-mark{display:grid;place-items:center;width:30px;height:30px;background:var(--green);color:#e2f5bf;font-family:Georgia,serif;font-size:20px;font-style:italic;border-radius:4px}
.brand-light{font-weight:500;color:#66816d}
.brand i{font-style:normal;font:9px 'DM Mono',monospace;letter-spacing:.07em;color:#929b93;margin-left:4px}
.turn-chip{display:flex;align-items:center;gap:10px;background:white;border:1px solid var(--line);border-radius:20px;padding:8px 13px;font:10px 'DM Mono',monospace;letter-spacing:.03em;color:#56645a}
.turn-chip b{color:var(--ink)}
.pulse,.live-dot,.feed-pip{width:7px;height:7px;border-radius:50%;background:#79b949;box-shadow:0 0 0 3px #79b94920}
.chip-divider{height:13px;width:1px;background:var(--line)}
.icon-btn{width:29px;height:29px;border:1px solid #d8dfd8;background:#fff;border-radius:50%;color:#526457;font-weight:700}
.commandbar{height:85px;display:flex;align-items:center;gap:34px;border-bottom:1px solid var(--line)}
.commander{display:flex;align-items:center;gap:11px;min-width:235px}
.flag-large{font-size:28px}
.commander small,.stat small{display:block;color:#8a958c;font:9px 'DM Mono',monospace;letter-spacing:.08em;margin-bottom:3px}
.commander strong{font-size:14px}
.change-nation{background:none;border:0;color:#7a8a7b;font:9px 'DM Mono',monospace;text-decoration:underline;text-underline-offset:3px;margin-left:2px}
.command-stats{display:flex;align-items:center;gap:35px;flex:1}
.stat{display:flex;align-items:center;gap:9px}
.stat-icon{display:grid;place-items:center;width:29px;height:29px;color:#52735a;background:#e9efe5;border-radius:8px;font-size:16px}
.money-icon{font:16px 'DM Mono',monospace}
.stat strong{font-size:14px}
.end-turn{height:40px;padding:0 15px;border:0;border-radius:5px;background:#1f5438;color:#fff;display:flex;align-items:center;gap:14px;font:10px 'DM Mono',monospace;letter-spacing:.05em}
.end-turn b{font-size:17px;color:var(--bright)}
.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 354px;gap:24px;padding-top:21px}
.map-column{min-width:0}
.map-toolbar{height:50px;display:flex;justify-content:space-between;align-items:flex-start}
.eyebrow{font:9px 'DM Mono',monospace;color:#849087;letter-spacing:.12em}
.map-title h1{font-size:19px;letter-spacing:-.03em;margin:4px 0}
.live-dot{display:inline-block;width:6px;height:6px;vertical-align:middle;margin-left:5px}
.map-tools{display:flex;align-items:center;gap:16px}
.legend{display:flex;gap:13px;color:#69756b;font-size:9px}
.legend span{display:flex;align-items:center;gap:5px}
.legend i{width:7px;height:7px;border-radius:2px;background:#d1d9d0}
.legend-player{background:#bad889!important}
.legend-war{background:#da8175!important}
.legend-ally{background:#74aaa1!important}
.tool-button{padding:6px 8px;background:#fff;border:1px solid var(--line);border-radius:4px;color:#6b796e;font-size:13px}
.tool-button span{font:9px 'DM Mono',monospace}
.map-frame{height:min(58vh,570px);min-height:360px;position:relative;overflow:hidden;border:1px solid #dfe5dc;border-radius:8px;background:#eaf0e8;box-shadow:0 7px 25px #3547350b;touch-action:none}
#world-map{width:100%;height:100%;display:block;cursor:grab}
#world-map:active{cursor:grabbing}
.map-loading{position:absolute;inset:0;display:grid;place-content:center;justify-items:center;gap:10px;background:#eaf0e8;color:#69806e;font:11px 'DM Mono',monospace;transition:opacity .3s;pointer-events:none}
.map-loading.hidden{opacity:0}
.loading-ring{width:24px;height:24px;border:2px solid #ccd9ca;border-top-color:#51835a;border-radius:50%;animation:spin .8s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}
}
.map-coordinates{position:absolute;left:13px;top:12px;display:flex;gap:11px;color:#6b7b6b;background:#f7f9f4d9;border:1px solid #dce5d8;border-radius:3px;padding:6px 8px;font:8px 'DM Mono',monospace;pointer-events:none}
.map-coordinates span:first-child{color:#507954}
.map-hint{position:absolute;left:50%;bottom:12px;transform:translateX(-50%);white-space:nowrap;color:#607263;background:#f7f9f4d9;border:1px solid #dce5d8;border-radius:3px;padding:6px 9px;font:8px 'DM Mono',monospace;letter-spacing:.08em;pointer-events:none}
.map-zoom{position:absolute;right:12px;bottom:12px;display:grid;gap:4px}
.map-zoom button{width:29px;height:29px;border:1px solid #d5ded2;background:#f8faf6eF;border-radius:4px;color:#4f6755;font-size:17px}
.map-tooltip{position:absolute;display:none;background:#172b20;color:white;padding:7px 9px;border-radius:4px;font-size:11px;pointer-events:none;z-index:2;box-shadow:0 4px 15px #172b2040}
.map-footer{display:flex;justify-content:space-between;padding:9px 2px;color:#8c968d;font:8px 'DM Mono',monospace;letter-spacing:.035em}
.map-footer b{color:#aebaab}
.intel-panel{background:white;border:1px solid #e1e6df;border-radius:7px;min-height:570px;display:flex;flex-direction:column;overflow:hidden}
.panel-tabs{display:flex;height:46px;border-bottom:1px solid var(--line)}
.tab{flex:1;border:0;background:#fff;color:#89938a;font:9px 'DM Mono',monospace;letter-spacing:.06em;border-bottom:2px solid transparent}
.tab.active{color:#335e41;border-bottom-color:#5c9461}
.tab span{display:inline-grid;place-items:center;background:#edf2eb;border-radius:8px;min-width:17px;height:16px;margin-left:3px;font-size:8px}
.tab-content{display:none;padding:17px 18px;flex:1}
.tab-content.active{display:block}
.nation-head{display:flex;align-items:center;gap:12px}
.nation-flag{font-size:34px;line-height:1}
.nation-head h2,.forces-heading h2{margin:3px 0 0;font-size:21px;letter-spacing:-.04em}
.nation-head .eyebrow{font-size:8px}
.bookmark{margin-left:auto;background:#f8faf7;border:1px solid var(--line);border-radius:4px;width:29px;height:29px;color:#647368}
.nation-tags{display:flex;gap:5px;margin:13px 0}
.tag{padding:4px 7px;border-radius:3px;background:#f2f4f1;color:#748076;font:8px 'DM Mono',monospace;letter-spacing:.05em}
.tag.ally{background:#e8f4ed;color:#3e7954}
.tag.war{background:#faeae7;color:#b45448}
.tag.player{background:#eff5df;color:#587c35}
.power-card{background:#f7f9f6;border:1px solid #edf0eb;border-radius:5px;padding:12px;margin:12px 0}
.power-label,.power-foot{display:flex;align-items:center;justify-content:space-between}
.power-label>span,.power-foot>span,.metric small{font:8px 'DM Mono',monospace;color:#89948a;letter-spacing:.06em}
.power-label strong{font:12px 'DM Mono',monospace}
.power-label small{font-size:7px;color:#919c91}
.power-track{height:5px;border-radius:5px;background:#e4e9e2;margin:10px 0 8px;overflow:hidden}
.power-track i{display:block;width:60%;height:100%;border-radius:5px;background:#79a95d;transition:width .4s}
.power-foot strong{font:10px 'DM Mono',monospace}
.metrics-grid{display:grid;grid-template-columns:1fr 1fr;border:1px solid #edf0eb;border-radius:5px;margin:12px 0}
.metric{padding:10px 11px;min-height:54px}
.metric:nth-child(odd){border-right:1px solid #edf0eb}
.metric:nth-child(-n+2){border-bottom:1px solid #edf0eb}
.metric strong{display:block;font-size:14px;margin-top:3px}
.metric em{font-size:9px;font-style:normal;color:#829086;font-weight:500}
.metric strong span{font-size:10px;color:#829086}
.section-rule{display:flex;align-items:center;gap:8px;margin:15px 0 9px;color:#839087;font:8px 'DM Mono',monospace;letter-spacing:.1em}
.section-rule i{height:1px;background:#edf0eb;flex:1}
.diplomacy-actions{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.action-btn{height:34px;background:#fff;border:1px solid #dfe6dc;border-radius:4px;text-align:left;padding:0 8px;color:#48634e;font-size:10px}
.action-btn span{margin-right:4px;color:#75975d}
.war-btn{color:#a54f49;border-color:#efdfdc}
.war-btn span{color:#cb6557}
.demand-btn{grid-column:span 2;color:#697568}
.notice{font-size:9px;line-height:1.45;color:#8b958c;padding:9px 0 0}
.panel-bottom{height:39px;border-top:1px solid #edf0eb;padding:0 15px;display:flex;align-items:center;justify-content:space-between}
.save-indicator{font:8px 'DM Mono',monospace;color:#89938b}
.save-indicator i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#86bd65;margin-right:5px}
.new-game{border:0;background:none;color:#89938b;font:8px 'DM Mono',monospace;text-decoration:underline;text-underline-offset:3px}
.forces-heading{margin-bottom:13px}
.forces-heading p{font-size:10px;color:#879188;margin:5px 0}
.unit-list{display:grid;gap:6px}
.unit-card{display:flex;align-items:center;gap:9px;border:1px solid #e8ece6;border-radius:5px;padding:8px}
.unit-icon{display:grid;place-items:center;width:32px;height:32px;background:#edf3e9;border-radius:5px;font-size:17px}
.unit-info{flex:1}
.unit-info strong{display:block;font-size:11px}
.unit-info small{color:#879188;font-size:8px}
.unit-buy{border:1px solid #dfe7dd;background:#f9fbf8;color:#436346;border-radius:4px;padding:6px 7px;font:9px 'DM Mono',monospace;white-space:nowrap}
.unit-buy b{display:block;font-size:8px;color:#88948a;margin-top:2px}
.custom-rule{margin-top:15px}
.design-box{border:1px solid #e6ebe3;border-radius:5px;padding:11px;background:#fbfcfa}
.design-top{display:flex;align-items:center;gap:8px;margin-bottom:11px}
.design-icon{display:grid;place-items:center;width:28px;height:28px;border-radius:5px;background:#edf3e9;color:#5d8a52;font-size:18px}
.design-top strong{display:block;font-size:10px}
.design-top small{display:block;color:#89938a;font-size:8px;margin-top:2px}
.design-stamp{margin-left:auto;padding:3px 5px;border:1px solid #d9e8ca;border-radius:3px;color:#799857;font:7px 'DM Mono',monospace}
.field-label,.design-row label{display:block;color:#88938a;font:8px 'DM Mono',monospace;letter-spacing:.06em}
.design-box input[type=text],.design-box input:not([type]){width:100%;height:31px;border:1px solid #e1e7de;border-radius:4px;padding:0 8px;margin:5px 0 9px;color:#34433a;font-size:10px;background:#fff}
.design-row{display:flex;gap:16px}
.design-row label{flex:1}
.design-row input[type=number]{display:block;width:100%;height:27px;border:1px solid #e1e7de;border-radius:4px;margin-top:5px;padding:0 6px;font-size:10px}
.design-row input[type=range]{width:100%;height:11px;accent-color:#638d52;vertical-align:middle;margin:7px 0 0}
.design-row label span{float:right;font:8px 'DM Mono',monospace;color:#71806f;margin-top:4px}
.design-cost{display:flex;justify-content:space-between;border-top:1px solid #edf0eb;margin-top:9px;padding-top:8px;color:#89938a;font:8px 'DM Mono',monospace}
.design-cost strong{color:#506747;font-size:10px}
.build-custom{width:100%;height:31px;background:#315e3f;border:0;color:#fff;border-radius:4px;margin-top:9px;text-align:left;padding:0 9px;font:9px 'DM Mono',monospace;letter-spacing:.03em}
.build-custom span{float:right;color:#c5ed76;font-size:15px}
.force-note{font-size:8px;color:#929b93;margin-top:9px;line-height:1.4}
.bottom-strip{height:47px;margin-top:6px;background:#fff;border:1px solid #e3e8e1;border-radius:5px;display:flex;align-items:center;padding:0 12px;gap:13px}
.feed-title{white-space:nowrap;color:#728075;font:8px 'DM Mono',monospace;letter-spacing:.06em}
.feed-pip{display:inline-block;width:6px;height:6px;margin-right:6px}
.feed-items{font-size:10px;color:#647167;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}
.dispatch b{font:9px 'DM Mono',monospace;color:#9aa39b;margin-right:7px}
.dispatch strong{color:#344d38}
.feed-next{border:0;background:none;color:#819083}
.toast{position:fixed;left:50%;bottom:25px;z-index:9;transform:translate(-50%,20px);opacity:0;transition:.25s;background:#193b29;color:white;border:1px solid #4d7455;border-radius:5px;padding:10px 15px;font-size:12px;box-shadow:0 8px 25px #152b1d30;pointer-eve
.toast.show{opacity:1;transform:translate(-50%,0)}
dialog{width:min(520px,calc(100% - 30px));border:1px solid #dce5da;border-radius:10px;padding:28px;color:var(--ink);box-shadow:0 24px 80px #12271945}
dialog::backdrop{background:#10211885;backdrop-filter:blur(3px)}
dialog h2{font-size:25px;margin:6px 0}
dialog p{font-size:13px;line-height:1.6;color:#69766c}
.dialog-close{position:absolute;right:15px;top:12px;background:none;border:0;font-size:25px;color:#879188}
.guide-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.guide-grid div{background:#f5f8f3;border:1px solid #e8ede5;border-radius:5px;padding:10px}
.guide-grid b,.guide-grid span{display:block}
.guide-grid b{font:9px 'DM Mono',monospace;color:#45694a;margin-bottom:5px}
.guide-grid span{font-size:10px;color:#778178;line-height:1.4}
.guide-source{font-size:9px!important;border-top:1px solid var(--line);padding-top:10px}

