    const rect = mapFrame.getBoundingClientRect();
    tip.style.left = `${Math.max(8, Math.min(rect.width - 190, event.clientX - rect.left + 13))}px`;
    tip.style.top = `${Math.max(8, Math.min(rect.height - 60, event.clientY - rect.top + 13))}px`;
