  }
  function focusCountry(country) {
    if (!country) return;
    scale = Math.max(scale, 2.2);
    const point = project(+country.feature.properties.lon || 0, +country.feature.properties.lat || 0);
    offset = { x: -scale * (point.x - mapWidth / 2), y: -scale * (point.y - mapHeight / 2) };
    drawMap();
  }

